package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.media.*;import android.media.session.*;import android.os.*;import android.view.*;import java.io.*;import java.util.concurrent.*;
/** Exercises the optional workspace and a real Android MediaSession; restores listener access. */
public class DrivingWorkspaceChecks extends Instrumentation {
 LauncherActivity a;MediaSession session;boolean hadAccess;int checks;
 void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
 void ui(Runnable work){Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 View find(View v,String name){if(name.equals(v.getContentDescription()==null?"":v.getContentDescription().toString()))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View f=find(g.getChildAt(i),name);if(f!=null)return f;}}return null;}
 void shell(String cmd)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(cmd);InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] buffer=new byte[1024];while(in.read(buffer)!=-1){}}}
 void waitFor(java.util.concurrent.Callable<Boolean> predicate,String why)throws Exception{long until=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<until){if(predicate.call()){check(true,why);return;}Thread.sleep(100);}throw new AssertionError(why);}
 void state(int state){session.setPlaybackState(new PlaybackState.Builder().setState(state,0,1).setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE).build());}
 void screenshot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image==null)return;try(OutputStream out=new FileOutputStream(new File(a.getFilesDir(),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  NotificationManager nm=(NotificationManager)getTargetContext().getSystemService(Context.NOTIFICATION_SERVICE);hadAccess=nm.isNotificationListenerAccessGranted(new ComponentName(getTargetContext(),MediaAccessService.class));
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));CountDownLatch ready=new CountDownLatch(1);a.worker.execute(()->a.main.post(ready::countDown));check(ready.await(45,TimeUnit.SECONDS),"catalog ready");waitForIdleSync();
  ui(()->{a.showApps();View entry=find(a.stage,"Open driving workspace");check(entry!=null,"workspace discoverable from Apps");entry.performClick();check("road".equals(a.page)&&a.drivingWorkspace!=null,"entry opens workspace");check(a.drivingWorkspace.tabs.getChildCount()==3,"three top-level tabs");for(int i=0;i<3;i++)check(a.drivingWorkspace.tabButtons[i].isFocusable(),"tab supports hardware focus "+i);check(a.drivingWorkspace.appGrid!=null,"reuses paged app grid");});
  DrivingWorkspace workspace=a.drivingWorkspace;
  ui(()->{check(find(a.stage,"Favorite Files")==null&&find(a.stage,"Control Center")==null,"workspace does not duplicate Home chrome");check(workspace.getHeight()>=a.stage.getHeight()-a.dp(24),"workspace uses available screen height");});screenshot("driving-workspace-apps.png");
  ui(()->{workspace.select(DrivingTemplates.ACTIONS);check(workspace.content.getChildCount()==4,"action list has four rows");for(int i=0;i<4;i++)check(workspace.content.getChildAt(i).getLayoutParams().height>=a.dp(56),"large action target "+i);workspace.launch("",new String[]{"missing.template.test"});check(workspace.alert!=null&&workspace.alert.getButton(AlertDialog.BUTTON_POSITIVE).getVisibility()==View.VISIBLE&&workspace.alert.getButton(AlertDialog.BUTTON_NEGATIVE).getVisibility()==View.VISIBLE,"missing app alert has two clear actions");AlertDialog missing=workspace.alert;workspace.pause();check(!missing.isShowing()&&workspace.alert==null,"pause dismisses alert");workspace.select(999);check(a.drivingTab==DrivingTemplates.APPS,"invalid tab restored to Apps");workspace.select(DrivingTemplates.NOW_PLAYING);});
  shell("cmd notification allow_listener com.shazwan.idash3/.MediaAccessService");waitFor(()->workspace.media.granted(),"listener permission observed");
  ui(()->{session=new MediaSession(getTargetContext(),"DrivingWorkspaceChecks");session.setFlags(MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS|MediaSession.FLAG_HANDLES_MEDIA_BUTTONS);session.setCallback(new MediaSession.Callback(){public void onPause(){state(PlaybackState.STATE_PAUSED);}public void onPlay(){state(PlaybackState.STATE_PLAYING);}},new Handler(Looper.getMainLooper()));session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,"Workspace fixture").putString(MediaMetadata.METADATA_KEY_ARTIST,"Local test").build());state(PlaybackState.STATE_PLAYING);session.setActive(true);workspace.media.reload();});
  waitFor(()->"Workspace fixture".equals(workspace.media.title.getText().toString()),"real session title reaches template");ControlMedia previous=workspace.media;screenshot("driving-workspace-media.png");
  ui(()->{check(previous.play.isEnabled()&&!previous.previous.isEnabled()&&!previous.next.isEnabled(),"only supported controls enabled");previous.play.performClick();});waitFor(()->previous.controller!=null&&previous.controller.getPlaybackState().getState()==PlaybackState.STATE_PAUSED,"pause controls real session");
  ui(()->previous.play.performClick());waitFor(()->previous.controller!=null&&previous.controller.getPlaybackState().getState()==PlaybackState.STATE_PLAYING,"play controls real session");
  ui(()->{workspace.select(DrivingTemplates.APPS);check(!previous.active&&!previous.listening&&previous.controller==null&&!previous.registered,"tab switch releases callbacks");for(int i=0;i<8;i++){workspace.select(DrivingTemplates.NOW_PLAYING);ControlMedia m=workspace.media;workspace.select(DrivingTemplates.ACTIONS);check(!m.active&&!m.listening&&!m.registered,"repeated tab cleanup "+i);}a.onBackPressed();check("home".equals(a.page)&&a.drivingWorkspace==null,"Back returns Home and closes workspace");});
  result.putString("stream","PASS: "+checks+" driving template assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+checks+": "+e+"\n");}finally{if(session!=null)session.release();try{if(!hadAccess)shell("cmd notification disallow_listener com.shazwan.idash3/.MediaAccessService");}catch(Exception ignored){}if(a!=null)ui(a::finish);}finish(code,result);}
}
